drop policy if exists narrative_inputs_author_insert on public.narrative_inputs; create policy narrative_inputs_author_insert on public.narrative_inputs for insert to authenticated with check (author_id=(select auth.uid()) and status='pending' and (character_id is null or character_id in (select id from public.characters where owner_id=(select auth.uid()))) and (kind <> 'ideology' or target_character_id is not null));